data.query:
query Query($where: WorkcenterHistoryWhereInput, $orderBy: [WorkcenterHistoryOrderByInput!], $first: Int, $after: String) {
  workcenterHistory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        occurAt
        endAt
        transactionTypeId
        workcenterId
        mode {
          name
          color
          modeType {
            production
            maintenance
            other
            disabled
            off
            changeover
          }
        }
        event {
          name
        }
      }
    }
  }
}

data.transform:
(      
  $task := 
    $state.context.LOCAL.workcenterHistory#$i[transactionTypeId="Mode Change"].{
      "label": mode.name,
      "processId":1,
      "start": $moment(occurAt).format("DD/MM/YYYY HH:mm:ss"),
      "end": $isNilOrEmpty(endAt)? $moment().format("DD/MM/YYYY HH:mm:ss") : $moment(endAt).format("DD/MM/YYYY HH:mm:ss"),
      "id": "1-" & $i,
      "color": mode.color,
      "height": "100%",
      "toppadding": "0%"
    };

  $eventTask := 
    $state.context.LOCAL.workcenterHistory[transactionTypeId="Event Update"]#$e.{
      "label": event.name,
      "processId":1,
      "start": $moment(occurAt).format("DD/MM/YYYY HH:mm:ss"),
      "end":$moment(occurAt).format("DD/MM/YYYY HH:mm:ss"),
      "id": "e-" & $e,
      "color": "#ffffff",
      "height": ".1%",
      "toppadding": "99.9%"
    };

  $milestone :=  
    $state.context.LOCAL.workcenterHistory[transactionTypeId="Event Update"]#$m.{
      "date":  $moment(occurAt).format("DD/MM/YYYY HH:mm:ss"),
      "taskid":"e-" & $m,
      "color": "#000000",
      "shape": "polygon",
      "numSides":3,
      "tooltext": event.name & "{br}$date",
      "radius":10
    };
    $names := $uniq($state.context.LOCAL.workcenterHistory[transactionTypeId="Mode Change"].mode.name);

  $legend := {
    "item": $uniq($state.context.LOCAL.workcenterHistory[transactionTypeId="Mode Change"].mode.name)@$mn.{
      "label": $mn,
      "color": $uniq($state.context.LOCAL.workcenterHistory[transactionTypeId="Mode Change"].mode[name=$mn].color)[0]
      }


  };


  $start := $moment($task[0].start,'DD/MM/YYYY HH:mm:ss');
  $end := $moment($task[-1].end,'DD/MM/YYYY HH:mm:ss');
  $diff :=$end.diff($start,"hours");
  $dayArray := function($a,$c, $i, $r){
    (
      $startDay := $start.clone().add($i,'hours').startOf('hour').format('DD/MM/YYYY HH:mm:ss');
      $endDay := $start.clone().add($i,'hours').endOf('hour').format('DD/MM/YYYY HH:mm:ss');
      $label := $moment($endDay,'DD/MM/YYYY HH:mm:ss').format('MM/DD/YY HH:mm');
      $append($a,[{
        "start":$startDay,
        "end":$endDay,
        "label" :$label

        }]
      )
    )
  };
  $category := $reduce([0..$diff+1],$dayArray,[]);


  {
    "task": $append($eventTask,$task),
    "milestone":[$milestone],
    "legend": $legend,
    "category": [$category],
    "caption": "Workcenter Modes"
  }
)

